import { _decorator, Component, Node, Vec3, Color, input, Input, EventKeyboard, KeyCode } from 'cc';
import { EventBus, GameEvents } from '../core/EventBus';
import { createPrimitiveNode, Palette } from '../core/PrimitiveFactory';
import { buildHumanoid } from '../core/CharacterBuilder';
const { ccclass } = _decorator;

export interface NPCDef {
    id: string;
    name: string;
    role: string; // Elder, Hunter, Priest, Blacksmith, Merchant
    pos: Vec3;
    color: Color;
    greet: string;
}

export const NPCDefs: NPCDef[] = [
    { id: 'elder',      name: 'Village Elder',   role: 'Elder',      pos: new Vec3( 0,   0,   5), color: Palette.cloth,    greet: 'Brave traveler! Our village is in peril.' },
    { id: 'hunter',     name: 'Hunter Bram',     role: 'Hunter',     pos: new Vec3(-6,   0,   2), color: Palette.leather,  greet: 'Wolves prowl these woods, friend.' },
    { id: 'priest',     name: 'Father Ode',      role: 'Priest',     pos: new Vec3( 6,   0,   2), color: new Color(230,230,230), greet: 'May the light guide your blade.' },
    { id: 'blacksmith', name: 'Smith Roderic',   role: 'Blacksmith', pos: new Vec3(-4,   0,   8), color: new Color(120,90,60),  greet: 'Need a stronger weapon? Bring me tusks.' },
    { id: 'merchant',   name: 'Merchant Liva',   role: 'Merchant',   pos: new Vec3( 4,   0,   8), color: new Color(150,90,140), greet: 'Goods for the bold! Trade me trophies.' },
];

@ccclass('NPC')
export class NPC extends Component {
    public def!: NPCDef;
    public player: Node | null = null;
    public interactRadius = 3.0;
    public marker: Node | null = null;
    private canInteract = false;

    onLoad() {
        input.on(Input.EventType.KEY_DOWN, this.onKey, this);
    }
    onDestroy() {
        input.off(Input.EventType.KEY_DOWN, this.onKey, this);
    }

    init(def: NPCDef, player: Node) {
        this.def = def;
        this.player = player;
    }

    private onKey(e: EventKeyboard) {
        if (!this.canInteract) return;
        if (e.keyCode === KeyCode.KEY_E || e.keyCode === KeyCode.KEY_T) {
            EventBus.emit(GameEvents.NPC_INTERACTED, this.def.id);
        }
    }

    update(dt: number) {
        if (!this.player) return;
        const a = this.node.worldPosition, b = this.player.worldPosition;
        const d = Math.hypot(a.x - b.x, a.z - b.z);
        const inRange = d <= this.interactRadius;
        if (inRange !== this.canInteract) {
            this.canInteract = inRange;
            if (this.marker) this.marker.active = inRange;
        }
        // Spin marker
        if (this.marker && this.marker.active) {
            this.marker.setRotationFromEuler(0, (Date.now() / 5) % 360, 0);
        }
    }
}

export function buildNpcNode(def: NPCDef): { root: Node; marker: Node } {
    const parts = buildHumanoid(def.name, { skin: Palette.skin, shirt: def.color, pants: Palette.woodDark, hair: Palette.hair });
    parts.root.setPosition(def.pos);

    // Interaction marker (yellow exclamation cube)
    const marker = createPrimitiveNode('Marker', 'box', new Vec3(0.25, 0.6, 0.25), Palette.questYellow);
    marker.setPosition(0, 2.9, 0);
    marker.active = false;
    parts.root.addChild(marker);

    return { root: parts.root, marker };
}